>{
  "goal_digest": "bec054dc7f2656f407b763caace88841627058dbcc9e778096fe5bee084fb2ff",
  "goal_obligations": [
    {
      "obligation_id": "OB-001",
      "observable_requirement": "HTTP API 提供 GET /api/tickets 并支持 q 和 status 参数",
      "required_phases": ["observe", "execute"]
    },
    {
      "obligation_id": "OB-002",
      "observable_requirement": "POST /api/tickets 接收 title 和 description，返回新工单",
      "required_phases": ["execute"]
    },
    {
      "obligation_id": "OB-003",
      "observable_requirement": "PATCH /api/tickets/ID 接收 assignee 和/或 status，返回更新工单",
      "required_phases": ["execute"]
    },
    {
      "obligation_id": "OB-004",
      "observable_requirement": "空白标题拒绝创建，非法 status 不得顺便修改 assignee",
      "required_phases": ["execute"]
    },
    {
      "obligation_id": "OB-005",
      "observable_requirement": "UI 提供 Ticket title、Ticket description 字段和 Create ticket 按钮",
      "required_phases": ["observe"]
    },
    {
      "obligation_id": "OB-006",
      "observable_requirement": "UI 提供 Search tickets 与 Status filter(all/open/closed)",
      "required_phases": ["observe"]
    },
    {
      "obligation_id": "OB-007",
      "observable_requirement": "每工单 article 名称为 Ticket 标题，展示描述和状态，内部 Assignee 字段、Assign 按钮",
      "required_phases": ["observe"]
    },
    {
      "obligation_id": "OB-008",
      "observable_requirement": "open 工单有 Close 按钮",
      "required_phases": ["observe"]
    },
    {
      "obligation_id": "OB-009",
      "observable_requirement": "GET / 提供页面，SQLite 持久化，停止服务再用同一个 PATH 启动后数据不丢失",
      "required_phases": ["execute", "observe"]
    },
    {
      "obligation_id": "OB-010",
      "observable_requirement": "所有 API 接收/返回 JSON，成功创建 HTTP 201、查询/更新 200；无效输入 400、缺失资源 404；返回错误对象含 error",
      "required_phases": ["execute"]
    },
    {
      "obligation_id": "OB-011",
      "observable_requirement": "id 为稳定唯一值，多个独立浏览器看到相同服务数据",
      "required_phases": ["execute", "observe"]
    },
    {
      "obligation_id": "OB-012",
      "observable_requirement": "运行方式为 python server.py --host 127.0.0.1 --port PORT --db PATH，仅用 Python 标准库与原生浏览器功能",
      "required_phases": ["execute"]
    },
    {
      "obligation_id": "OB-013",
      "observable_requirement": "源码目录运行时可只读，数据库及运行文件写入 PATH 所在临时目录，不能写回源码",
      "required_phases": ["execute"]
    },
    {
      "obligation_id": "OB-014",
      "observable_requirement": "交付时保持工作区为自包含项目，README 说明启动与人工验证方法",
      "required_phases": ["observe"]
    }
  ],
  "add_stages": [
    {
      "stage": 1,
      "steps": [
        {
          "step_id": "S1-01",
          "objective": "创建项目骨架：README.md、server.py、static/index.html、static/style.css、static/app.js",
          "phase": "execute",
          "depends_on": [],
          "obligation_ids": ["OB-014"],
          "success_evidence": ["README.md 存在", "server.py 存在", "static/index.html 存在", "static/style.css 存在", "static/app.js 存在"]
        },
        {
          "step_id": "S1-02",
          "objective": "实现 SQLite 持久化数据模型、工单 CRUD 和状态校验",
          "phase": "execute",
          "depends_on": ["S1-01"],
          "obligation_ids": ["OB-002", "OB-003", "OB-004", "OB-009"],
          "success_evidence": ["server.py 包含 SQLite 数据库初始化", "server.py 包含工单 CRUD 路由", "server.py 包含状态校验逻辑"]
        },
        {
          "step_id": "S1-03",
          "objective": "实现 API 路由：GET /api/tickets、POST /api/tickets、PATCH /api/tickets/ID",
          "phase": "execute",
          "depends_on": ["S1-02"],
          "obligation_ids": ["OB-001", "OB-003", "OB-004", "OB-005", "OB-006", "OB-007", "OB-008", "OB-009", "OB-010", "OB-011", "OB-012"],
          "success_evidence": ["server.py 包含 GET /api/tickets 路由", "server.py 包含 POST /api/tickets 路由", "server.py 包含 PATCH /api/tickets/ID 路由", "server.py 包含 q 参数搜索", "server.py 包含 status 过滤", "server.py 包含 id 唯一性校验", "server.py 包含 400/404 错误处理"]
        },
        {
          "step_id": "S1-04",
          "objective": "实现 UI 页面：Ticket title、Ticket description 字段、Create ticket 按钮、Search tickets 与 Status filter(all/open/closed)",
          "phase": "execute",
          "depends_on": ["S1-03"],
          "obligation_ids": ["OB-005", "OB-006", "OB-007", "OB-008", "OB-011", "OB-012"],
          "success_evidence": ["static/index.html 包含 Ticket title 字段", "static/index.html 包含 Ticket description 字段", "static/index.html 包含 Create ticket 按钮", "static/index.html 包含 Search tickets 输入", "static/index.html 包含 Status filter 下拉", "static/index.html 包含 article 名称为 Ticket 标题", "static/index.html 包含 Assignee 字段", "static/index.html 包含 Assign 按钮", "static/index.html 包含 Close 按钮"]
        },
        {
          "step_id": "S1-05",
          "objective": "实现 UI 交互：Assign 按钮、Close 按钮、搜索和状态筛选",
          "phase": "execute",
          "depends_on": ["S1-04"],
          "obligation_ids": ["OB-005", "OB-006", "OB-007", "OB-008", "OB-011", "OB-012"],
          "success_evidence": ["static/app.js 包含 Assign 按钮事件", "static/app.js 包含 Close 按钮事件", "static/app.js 包含搜索和状态筛选逻辑", "static/app.js 包含 id 唯一性校验"]
        },
        {
          "step_id": "S1-06",
          "objective": "实现自包含运行：server.py 使用 Python 标准库，仅用 Python 标准库与原生浏览器功能",
          "phase": "execute",
          "depends_on": ["S1-05"],
          "obligation_ids": ["OB-012"],
          "success_evidence": ["server.py 不依赖外部包", "server.py 使用 Python 标准库", "server.py 使用原生浏览器功能"]
        },
        {
          "step_id": "S1-07",
          "objective": "实现数据持久化：SQLite 数据库初始化、工单 CRUD 持久化、停止服务再用同一个 PATH 启动后数据不丢失",
          "phase": "execute",
          "depends_on": ["S1-06"],
          "obligation_ids": ["OB-009", "OB-011", "OB-012"],
          "success_evidence": ["server.py 包含 SQLite 数据库初始化", "server.py 包含工单 CRUD 持久化", "server.py 包含数据库路径参数化", "server.py 包含数据库连接关闭"]
        },
        {
          "step_id": "S1-08",
          "objective": "实现错误处理：无效输入 400、缺失资源 404、返回错误对象含 error",
          "phase": "execute",
          "depends_on": ["S1-07"],
          "obligation_ids": ["OB-009", "OB-010", "OB-011", "OB-012"],
          "success_evidence": ["server.py 包含 400 错误处理", "server.py 包含 404 错误处理", "server.py 包含错误对象含 error"]
        },
        {
          "step_id": "S1-09",
          "objective": "实现 id 唯一性校验：id 为稳定唯一值，多个独立浏览器看到相同服务数据",
          "phase": "execute",
          "depends_on": ["S1-08"],
          "obligation_ids": ["OB-011", "OB-012"],
          "success_evidence": ["server.py 包含 id 唯一性校验", "server.py 包含 id 生成逻辑"]
        },
        {
          "step_id": "S1-10",
          "objective": "实现源码目录运行：源码目录运行时可只读，数据库及运行文件写入 PATH 所在临时目录，不能写回源码",
          "phase": "execute",
          "depends_on": ["S1-09"],
          "obligation_ids": ["OB-013"],
          "success_evidence": ["server.py 包含临时目录写入逻辑", "server.py 包含源码目录只读校验"]
        },
        {
          "step_id": "S1-11",
          "objective": "实现交付要求：README.md 说明启动与人工验证方法",
          "phase": "execute",
          "depends_on": ["S1-10"],
          "obligation_ids": ["OB-014"],
          "success_evidence": ["README.md 包含启动说明", "README.md 包含人工验证方法"]
        }
      ]
    }
  ],
  "replace_stages": [],
